--

CREATE TABLE public.payment_records (
    id bigint NOT NULL,
    quiniela_id integer NOT NULL,
    user_id integer,
    amount integer NOT NULL,
    currency text DEFAULT 'MXN'::text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reference text,
    reviewed_by integer,
    notes text DEFAULT ''::text NOT NULL,
    confirmed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    CONSTRAINT payment_records_amount_check CHECK ((amount >= 0)),
    CONSTRAINT payment_records_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'webhook_recurrente'::text, 'webhook_paypal'::text]))),
    CONSTRAINT payment_records_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'confirmed'::text, 'refunded'::text, 'rejected'::text])))
);


